import{_ as t,o,c as a,ag as i}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Usage","description":"","frontmatter":{},"headers":[],"relativePath":"guide/use.md","filePath":"guide/use.md","lastUpdated":1792912409000}'),r={name:"guide/use.md"};function n(l,e,s,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h1><p>EasyYapi supports the following usage methods:</p><h2 id="method-1-export-via-shortcut" tabindex="-1">Method 1: Export via Shortcut <a class="header-anchor" href="#method-1-export-via-shortcut" aria-label="Permalink to &quot;Method 1: Export via Shortcut&quot;">​</a></h2><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Use shortcut <code>Alt + Shift + E</code> (Windows/Linux) or <code>Ctrl + E</code> (macOS)</li><li>Select the APIs to export</li><li>Choose the export channel: <code>YApi</code> / <code>Markdown</code> / <code>Postman</code></li><li>Click the ✔ button or press Enter to complete the export</li></ol><h2 id="method-2-export-via-right-click" tabindex="-1">Method 2: Export via Right-Click <a class="header-anchor" href="#method-2-export-via-right-click" aria-label="Permalink to &quot;Method 2: Export via Right-Click&quot;">​</a></h2><ol><li>Open a file containing APIs in your project, or select files/folders in the IDEA project panel</li><li>Right-click on the file content or folder</li><li>Select <code>ExportYapi</code> / <code>ExportPostman</code> / <code>ExportMarkdown</code> to export all APIs in the file or folder</li></ol><h2 id="method-3-call-api" tabindex="-1">Method 3: Call API <a class="header-anchor" href="#method-3-call-api" aria-label="Permalink to &quot;Method 3: Call API&quot;">​</a></h2><ol><li>Open a file containing APIs in your project</li><li>Click the gutter icon next to the API method</li><li>Send API requests directly from the IDE</li></ol><p>See <a href="./call">Call API</a> for more details.</p><h2 id="export-only-selected-methods" tabindex="-1">Export Only Selected Methods <a class="header-anchor" href="#export-only-selected-methods" aria-label="Permalink to &quot;Export Only Selected Methods&quot;">​</a></h2><p>Since v3.2.0, EasyYapi respects method-level selection when exporting. Select one or more methods in the editor (either by caret or by selecting a text range that spans them) before triggering an export — only the endpoints whose source method matches (or overrides) the selection are exported, instead of every endpoint in the containing class.</p><p>This works for every export channel (YApi, Postman, Markdown, cURL, HttpClient, Hoppscotch, OpenAPI, ApiPost). If no methods are selected, the whole containing class is exported as before.</p><h2 id="export-a-contract-interface" tabindex="-1">Export a Contract Interface <a class="header-anchor" href="#export-a-contract-interface" aria-label="Permalink to &quot;Export a Contract Interface&quot;">​</a></h2><p>When the mapping annotations (<code>@RequestMapping</code> &amp; friends) sit on an interface and the framework annotation (<code>@RestController</code>) sits on its implementation — the usual server layout — point the export at the interface, or at a method on it. Since v3.2.6 the export expands the contract to its implementing classes and exports their endpoints, instead of failing with &quot;No API endpoints found&quot;.</p><p>A selection that names both halves of the layout (the contract interface and the API class that implements it) exports each endpoint once. Selections made in the Project view are unchanged: a directory selection exports only its own classes, never the implementations of interfaces it merely enumerates.</p><p>This works for every export channel.</p><h2 id="copy-an-api-url" tabindex="-1">Copy an API URL <a class="header-anchor" href="#copy-an-api-url" aria-label="Permalink to &quot;Copy an API URL&quot;">​</a></h2><ol><li>Select one or more methods, a class, or files/folders in the editor or the Project view</li><li>Right-click and choose <strong>EasyYapi</strong> &gt; <strong>Copy API URL</strong></li><li>The address of each endpoint in the selection is copied, one per line, as <code>METHOD /path</code></li></ol><p>Unlike the API Explorer&#39;s <strong>Copy Path</strong>, which copies only the path, <strong>Copy API URL</strong> includes the HTTP method — so <code>GET /user/{id}</code> and <code>PUT /user/{id}</code> stay distinguishable. It can be turned off in <strong>Features</strong> (<code>Copy API URL</code>).</p>',19)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
